div.script:

document.addEventListener('DOMContentLoaded', function() {
    const fileInput = document.getElementById('profile-photo-upload');
    if (fileInput) {
        fileInput.addEventListener('change', function(e) {
            if (this.files && this.files[0]) {
                uploadProfilePhoto(this.files[0]);
            }
        });
    }
});

function uploadProfilePhoto(file) {
    const formData = new FormData();
    formData.append('profile_photo', file);
    formData.append('csrf_token', document.querySelector('input[name="csrf_token"]').value);

    const uploadBtn = document.querySelector('.btn:has(.fa-camera)');
    if (uploadBtn) {
        uploadBtn.innerHTML = '<i class="fas fa-spinner fa-spin me-2"></i>Uploading...';
        uploadBtn.disabled = true;
    }

    fetch('/patient/portal/profile/upload-photo', {
        method: 'POST',
        body: formData
    })
    .then(response => response.json())
    .then(data => {
        if (data.success) {
            location.reload();
        } else {
            alert('Error uploading photo: ' + (data.error || 'Unknown error'));
            if (uploadBtn) {
                uploadBtn.innerHTML = '<i class="fas fa-camera me-2"></i>Upload Photo';
                uploadBtn.disabled = false;
            }
        }
    })
    .catch(error => {
        console.error('Error:', error);
        alert('Error uploading photo. Please try again.');
        if (uploadBtn) {
            uploadBtn.innerHTML = '<i class="fas fa-camera me-2"></i>Upload Photo';
            uploadBtn.disabled = false;
        }
    });
}

function removeProfilePhoto() {
    if (confirm('Are you sure you want to remove your profile photo?')) {
        const removeBtn = document.querySelector('.btn:has(.fa-trash)');
        if (removeBtn) {
            removeBtn.innerHTML = '<i class="fas fa-spinner fa-spin me-2"></i>Removing...';
            removeBtn.disabled = true;
        }

        fetch('/patient/portal/profile/remove-photo', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
            },
            body: JSON.stringify({
                csrf_token: document.querySelector('input[name="csrf_token"]').value
            })
        })
        .then(response => response.json())
        .then(data => {
            if (data.success) {
                location.reload();
            } else {
                alert('Error removing photo: ' + (data.error || 'Unknown error'));
                if (removeBtn) {
                    removeBtn.innerHTML = '<i class="fas fa-trash me-2"></i>Remove Photo';
                    removeBtn.disabled = false;
                }
            }
        })
        .catch(error => {
            console.error('Error:', error);
            alert('Error removing photo. Please try again.');
            if (removeBtn) {
                removeBtn.innerHTML = '<i class="fas fa-trash me-2"></i>Remove Photo';
                removeBtn.disabled = false;
            }
        });
    }
}

t.script:

// Simple global functions for onclick handlers
window.selectHorizontalDate = function(dateElement) {
    // Prevent multiple selections - check if already selected
    if (dateElement.classList.contains('date-item-selected')) {
        return; // Do nothing if already selected
    }

    // Remove ALL previous selections first
    document.querySelectorAll('.date-item-selected').forEach(el => {
        el.classList.remove('date-item-selected');
    });

    // Add selection to clicked date only
    dateElement.classList.add('date-item-selected');

    const selectedDate = dateElement.getAttribute('data-date');
    const selectedDateObj = new Date(selectedDate + 'T00:00:00');
    const formattedDate = selectedDateObj.toLocaleDateString('en-US', { 
        year: 'numeric', 
        month: 'long', 
        day: 'numeric' 
    });

    // Update selected date title
    const titleElement = document.getElementById('selected-date-title');
    if (titleElement) {
        titleElement.textContent = formattedDate;
    }

    // Show the selected date appointments section
    const selectedSection = document.getElementById('selected-date-appointments');
    if (selectedSection) {
        selectedSection.style.display = 'block';
        selectedSection.classList.add('selected-date-section');

        // Scroll to the section
        setTimeout(() => {
            selectedSection.scrollIntoView({ behavior: 'smooth', block: 'start' });
        }, 100);
    }

    // Load appointments for the selected date
    loadAppointmentsForDate(selectedDate);
}

window.navigateDateBar = function(dayOffset) {
    // Prevent multiple clicks
    if (window.navigating) return;
    window.navigating = true;

    try {
        const currentUrl = new URL(window.location);
        let currentDate;

        // Get current date from URL or use today
        if (currentUrl.searchParams.has('date')) {
            currentDate = new Date(currentUrl.searchParams.get('date'));
        } else {
            currentDate = new Date();
        }

        // Calculate new date
        const newDate = new Date(currentDate);
        newDate.setDate(currentDate.getDate() + dayOffset);

        // Update URL and navigate
        const newUrl = new URL(window.location.pathname, window.location.origin);
        newUrl.searchParams.set('date', newDate.toISOString().split('T')[0]);

        // Preserve filters
        const doctorFilter = document.getElementById('doctor_filter') ? document.getElementById('doctor_filter').value : '';
        const statusFilter = document.getElementById('status_filter') ? document.getElementById('status_filter').value : '';

        if (doctorFilter) newUrl.searchParams.set('doctor', doctorFilter);
        if (statusFilter) newUrl.searchParams.set('status', statusFilter);

        // Remove selected_date to avoid conflicts
        newUrl.searchParams.delete('selected_date');

        // Navigate without jumping using replace
        window.location.replace(newUrl.toString());
    } catch (e) {
        console.error('Navigation error:', e);
        window.navigating = false;
    }
}

document.addEventListener('DOMContentLoaded', function() {
    // Initialize calendar functionality
    initializeCalendar();

    // Clear any existing selections first
    document.querySelectorAll('.date-item-selected').forEach(el => {
        el.classList.remove('date-item-selected');
    });

    // Only highlight today's date if no specific date is already selected from URL
    const urlParams = new URLSearchParams(window.location.search);
    const selectedDateParam = urlParams.get('selected_date');

    if (!selectedDateParam) {
        const today = new Date().toISOString().split('T')[0];
        const todayElement = document.querySelector(`[data-date="${today}"]`);
        if (todayElement) {
            todayElement.classList.add('date-item-selected');
            // Auto-load appointments for today
            setTimeout(() => {
                loadAppointmentsForDate(today);
            }, 100);
        }
    } else {
        // Highlight the selected date from URL without triggering reload
        const selectedElement = document.querySelector(`[data-date="${selectedDateParam}"]`);
        if (selectedElement) {
            selectedElement.classList.add('date-item-selected');
        }
    }
});

function initializeCalendar() {
    // Add click event listeners to date items
    document.querySelectorAll('.date-item').forEach(dateElement => {
        dateElement.addEventListener('click', function() {
            selectHorizontalDate(this);
        });
    });
}

// Global function for loading appointments by date
window.loadAppointmentsForDate = function(date) {
    // Show loading state
    showLoadingForDate(date);

    // Update browser URL without reloading
    const url = new URL(window.location);
    url.searchParams.set('selected_date', date);

    // Preserve existing filters
    const doctorFilter = document.getElementById('doctor_filter') ? document.getElementById('doctor_filter').value : '';
    const statusFilter = document.getElementById('status_filter') ? document.getElementById('status_filter').value : '';

    if (doctorFilter) url.searchParams.set('doctor', doctorFilter);
    if (statusFilter) url.searchParams.set('status', statusFilter);

    window.history.pushState({}, '', url.toString());

    // Make AJAX request to load appointments for the selected date
    fetch(`/patient/portal/appointments/ajax?selected_date=${date}&amp;doctor=${doctorFilter}&amp;status=${statusFilter}`, {
        method: 'GET',
        headers: {
            'X-Requested-With': 'XMLHttpRequest',
            'Content-Type': 'application/json',
        }
    })
    .then(response => {
        if (!response.ok) {
            throw new Error('Network response was not ok');
        }
        return response.json();
    })
    .then(data => {
        updateAppointmentsDisplay(data, date);
    })
    .catch(error => {
        console.error('Error loading appointments:', error);
        showErrorMessage('Failed to load appointments for selected date. Please try again.');
    });
}

window.showLoadingForDate = function(date) {
    const selectedSection = document.getElementById('selected-date-appointments');
    if (!selectedSection) {
        console.error('Selected appointments section not found!');
        return;
    }

    // Clear existing content and show the section
    selectedSection.innerHTML = '';
    selectedSection.style.display = 'block';

    const section = document.getElementById('selected-date-appointments');
    const formattedDate = new Date(date + 'T00:00:00').toLocaleDateString('en-US', { 
        year: 'numeric', 
        month: 'long', 
        day: 'numeric' 
    });

    section.innerHTML = `
        <h3 class="section-title mb-4">
            <i class="fas fa-calendar-day me-2"></i>
            <span id="selected-date-title">Appointments for ${formattedDate}</span>
        </h3>
        <div class="text-center py-4">
            <div class="spinner-border text-primary" role="status">
                <span class="visually-hidden">Loading...</span>
            </div>
            <p class="mt-2 text-muted">Loading appointments...</p>
        </div>
    `;
    section.style.display = 'block';
}

window.updateAppointmentsDisplay = function(data, date) {
    const section = document.getElementById('selected-date-appointments');
    if (!section) return;

    const formattedDate = new Date(date + 'T00:00:00').toLocaleDateString('en-US', { 
        year: 'numeric', 
        month: 'long', 
        day: 'numeric' 
    });

    if (data.appointments && data.appointments.length > 0) {
        let appointmentsHtml = `
            <h3 class="section-title mb-4">
                <i class="fas fa-calendar-day me-2"></i>
                <span id="selected-date-title">Appointments for ${formattedDate}</span>
            </h3>
            <div class="activity-list">
        `;

        data.appointments.forEach(appointment => {
            const appointmentState = appointment.state || 'upcoming';
            const badgeClass = `badge-gradient-${appointmentState.toLowerCase()}`;
            const iconClass = appointmentState.toLowerCase();
            const statusText = appointmentState.charAt(0).toUpperCase() + appointmentState.slice(1);
            const appointmentTime = new Date(appointment.appointment_date).toLocaleTimeString('en-US', {
                hour: 'numeric',
                minute: '2-digit',
                hour12: true
            });

            appointmentsHtml += `
                <div class="enhanced-appointment-card">
                    <div class="appointment-card-header">
                        <div class="appointment-number-badge">${appointment.name || `APT-${appointment.id}`}</div>
                        <div class="appointment-status-badge">
                            <span class="badge ${badgeClass}">${statusText}</span>
                        </div>
                    </div>

                    <div class="appointment-card-body">
                        <div class="doctor-profile-section">
                            <div class="doctor-profile-image-container">
                                ${appointment.doctor_image ? 
                                    `<img src="data:image/png;base64,${appointment.doctor_image}" class="doctor-profile-img"/>` :
                                    `<div class="doctor-profile-placeholder">
                                        <i class="fas fa-user-md"></i>
                                    </div>`
                                }
                            </div>
                            <div class="doctor-info">
                                <div class="doctor-name d-flex justify-content-between align-items-center">
                                    <div>
                                        ${appointment.doctor_name || 'General Appointment'}
                                        ${appointment.doctor_degrees && appointment.doctor_degrees.trim() !== '' ? 
                                            `<small style="color: #667eea; font-weight: 500;"> (${appointment.doctor_degrees})</small>` : 
                                            ''}
                                        ${appointment.doctor_specialty && 
                                          appointment.doctor_specialty !== 'oeh.medical.specialty()' && 
                                          appointment.doctor_specialty.trim() !== '' && 
                                          appointment.doctor_specialty !== 'None' ? 
                                          `<small style="color: #6b7280; font-weight: normal;"> - ${appointment.doctor_specialty}</small>` : 
                                          ''}
                                    </div>
                                    <a href="/patient/portal/appointment/${appointment.id}" class="btn btn-primary btn-sm">
                                        <i class="fas fa-eye me-1"></i>View Details
                                    </a>
                                </div>
                            </div>
                        </div>

                        <div class="appointment-details-grid">
                            <div class="detail-item">
                                <i class="fas fa-clock"></i>
                                <span>${appointmentTime}</span>
                            </div>
                            <div class="detail-item">
                                <i class="fas fa-calendar-check"></i>
                                <span>${appointment.appointment_type}</span>
                            </div>
                            <div class="detail-item">
                                <i class="fas fa-hospital"></i>
                                <span>${appointment.institution_name || 'Clinic'}</span>
                            </div>
                            ${appointment.priority && appointment.priority !== 'normal' ? `
                                <div class="detail-item priority-item priority-${appointment.priority}">
                                    <i class="fas fa-exclamation-triangle"></i>
                                    <span>${appointment.priority.charAt(0).toUpperCase() + appointment.priority.slice(1)} Priority</span>
                                </div>
                            ` : ''}
                        </div>

                        <div class="appointment-actions-row">
                            ${appointment.online_meeting_link ? `
                                <button class="btn-meeting" onclick="window.open('${appointment.online_meeting_link}', '_blank')">
                                    <i class="fas fa-video"></i>
                                    Join Meeting
                                </button>
                            ` : ''}
                        </div>
                    </div>
                </div>
            `;
        });

        appointmentsHtml += '</div>';
        section.innerHTML = appointmentsHtml;
    } else {
        section.innerHTML = `
            <h3 class="section-title mb-4">
                <i class="fas fa-calendar-day me-2"></i>
                <span id="selected-date-title">Appointments for ${formattedDate}</span>
            </h3>
            <div class="text-center py-5">
                <i class="fas fa-calendar-times fa-4x text-muted mb-3"></i>
                <h4 class="text-muted">No Appointments Found</h4>
                <p class="text-muted">You don't have any appointments scheduled for this date.</p>
            </div>
        `;
    }

    // Scroll to the section
    setTimeout(() => {
        section.scrollIntoView({ behavior: 'smooth', block: 'start' });
    }, 100);
}

window.showErrorMessage = function(message) {
    const section = document.getElementById('selected-date-appointments');
    if (section) {
        section.innerHTML = `
            <div class="alert alert-danger">
                <i class="fas fa-exclamation-circle me-2"></i>
                ${message}
            </div>
        `;
    }
}

// Auto-scroll to center selected date
setTimeout(() => {
    const selectedDate = document.querySelector('.date-item-selected');
    const dateBar = document.getElementById('horizontal-date-bar');

    if (selectedDate && dateBar) {
        const containerWidth = dateBar.offsetWidth;
        const selectedLeft = selectedDate.offsetLeft;
        const selectedWidth = selectedDate.offsetWidth;

        // Calculate scroll position to center the selected date
        const scrollLeft = selectedLeft - (containerWidth / 2) + (selectedWidth / 2);

        dateBar.scrollTo({
            left: scrollLeft,
            behavior: 'smooth'
        });
    }
}, 300);

function navigateDateBar(dayOffset) {
    // Prevent multiple clicks
    if (window.navigating) return;
    window.navigating = true;

    try {
        const currentUrl = new URL(window.location);
        let currentDate;

        if (dayOffset === 0) {
            // Navigate to today
            currentDate = new Date();
        } else {
            // Get current date from URL parameter or use today
            const currentDateParam = currentUrl.searchParams.get('date');
            if (currentDateParam) {
                currentDate = new Date(currentDateParam);
            } else {
                currentDate = new Date();
            }
            currentDate.setDate(currentDate.getDate() + dayOffset);
        }

        const newDateString = currentDate.toISOString().split('T')[0];

        // Build new URL
        const newUrl = new URL(window.location);
        newUrl.searchParams.set('date', newDateString);

        // Preserve existing filters
        const doctorFilter = currentUrl.searchParams.get('doctor');
        const statusFilter = currentUrl.searchParams.get('status');

        if (doctorFilter) newUrl.searchParams.set('doctor', doctorFilter);
        if (statusFilter) newUrl.searchParams.set('status', statusFilter);

        // Remove selected_date to avoid conflicts
        newUrl.searchParams.delete('selected_date');

        // Navigate without jumping using replace
        window.location.replace(newUrl.toString());
    } catch (e) {
        console.error('Navigation error:', e);
        window.navigating = false;
    }
}


// Auto-scroll to center selected date
document.addEventListener('DOMContentLoaded', function() {
    setTimeout(() => {
        const selectedDate = document.querySelector('.date-item-selected');
        const dateBar = document.getElementById('horizontal-date-bar');

        if (selectedDate && dateBar) {
            const containerWidth = dateBar.offsetWidth;
            const selectedLeft = selectedDate.offsetLeft;
            const selectedWidth = selectedDate.offsetWidth;

            // Calculate scroll position to center the selected date
            const scrollLeft = selectedLeft - (containerWidth / 2) + (selectedWidth / 2);

            dateBar.scrollTo({
                left: scrollLeft,
                behavior: 'smooth'
            });
        }
    }, 100);
});

function updateFilters() {
    const doctorFilter = document.getElementById('doctor_filter') ? document.getElementById('doctor_filter').value : '';
    const statusFilter = document.getElementById('status_filter') ? document.getElementById('status_filter').value : '';
    const currentDate = document.getElementById('date_picker') ? document.getElementById('date_picker').value : '';

    const url = new URL(window.location.pathname, window.location.origin);

    // Add parameters only if they have values
    if (currentDate) url.searchParams.set('date', currentDate);
    if (doctorFilter) url.searchParams.set('doctor', doctorFilter);
    if (statusFilter) url.searchParams.set('status', statusFilter);

    // Preserve selected_date if it exists
    const currentUrl = new URL(window.location);
    const selectedDate = currentUrl.searchParams.get('selected_date');
    if (selectedDate) url.searchParams.set('selected_date', selectedDate);

    window.location.href = url.toString();
}

// Add keyboard navigation
document.addEventListener('keydown', function(e) {
    const selectedDay = document.querySelector('.calendar-day-selected');
    if (!selectedDay) return;

    let targetDay = null;
    const allDays = Array.from(document.querySelectorAll('.calendar-day-clickable'));
    const currentIndex = allDays.indexOf(selectedDay);

    switch(e.key) {
        case 'ArrowLeft':
            targetDay = allDays[currentIndex - 1];
            break;
        case 'ArrowRight':
            targetDay = allDays[currentIndex + 1];
            break;
        case 'ArrowUp':
            targetDay = allDays[currentIndex - 7];
            break;
        case 'ArrowDown':
            targetDay = allDays[currentIndex + 7];
            break;
    }

    if (targetDay) {
        e.preventDefault();
        selectDate(targetDay);
    }
});

// Add appointment click handlers
document.addEventListener('click', function(e) {
    if (e.target.classList.contains('calendar-appointment')) {
        e.stopPropagation();
        // You could add appointment detail popup here
        console.log('Appointment clicked:', e.target.getAttribute('title'));
    }
});

// Enhanced appointment card functions
window.viewAppointmentDetails = function(appointmentId) {
    window.location.href = `/patient/portal/appointment/${appointmentId}`;
};

window.joinMeeting = function(meetingLink) {
    window.open(meetingLink, '_blank', 'noopener,noreferrer');
};


function selectHorizontalDate(dateElement) {
    console.log('Date clicked:', dateElement.getAttribute('data-date'));

    // Remove all selected classes
    var selected = document.querySelectorAll('.date-item-selected');
    for (var i = 0; i < selected.length; i++) {
        selected[i].classList.remove('date-item-selected');
    }

    // Add selected class to clicked element
    dateElement.classList.add('date-item-selected');

    // Get the date
    var selectedDate = dateElement.getAttribute('data-date');

    // Show loading in appointments section
    var section = document.getElementById('selected-date-appointments');
    if (!section) {
        console.error('Selected appointments section not found in CDATA function!');
        return;
    }

    // Clear existing content and show the section
    section.innerHTML = '';
    section.style.display = 'block';
        section.innerHTML = '<h3>Loading appointments for ' + selectedDate + '...</h3><div class="spinner-border"></div>';

        // Make AJAX request
        fetch('/patient/portal/appointments/ajax?selected_date=' + selectedDate)
        .then(function(response) { 
            console.log('Response status:', response.status);
            return response.json(); 
        })
        .then(function(data) {
            console.log('Appointments data:', data);

            // Format date professionally
            var dateObj = new Date(selectedDate + 'T00:00:00');
            var formattedDate = dateObj.toLocaleDateString('en-US', { 
                weekday: 'long',
                year: 'numeric', 
                month: 'long', 
                day: 'numeric' 
            });

            if (data.appointments && data.appointments.length > 0) {
                var html = '<h3><i class="fas fa-calendar-day me-2"></i>Appointments for ' + formattedDate + '</h3><div class="activity-list">';
                for (var i = 0; i < data.appointments.length; i++) {
                    var apt = data.appointments[i];
                    var aptDate = new Date(apt.appointment_date);
                    var aptTime = aptDate.toLocaleTimeString('en-US', {
                        hour: 'numeric',
                        minute: '2-digit',
                        hour12: true
                    });

                    html += '<div class="activity-item d-flex">';
                    html += '<div class="activity-icon upcoming"><i class="fas fa-clock"></i></div>';
                    html += '<div class="activity-card-content flex-grow-1">';
                    html += '<div class="appointment-info">';
                    html += '<div class="appointment-doctor"><strong>' + (apt.doctor_name || 'General Appointment') + '</strong></div>';
                    html += '<div class="appointment-id">' + apt.name + '</div>';
                    html += '</div>';
                    html += '<div class="appointment-meta">';
                    html += '<div class="appointment-detail"><i class="fas fa-clock me-1"></i><span>' + aptTime + '</span></div>';
                    if (apt.institution_name) {
                        html += '<div class="appointment-detail"><i class="fas fa-hospital me-1"></i><span>' + apt.institution_name + '</span></div>';
                    }
                    html += '</div>';
                    html += '</div></div>';
                }
                html += '</div>';
                section.innerHTML = html;
            } else {
                section.innerHTML = '<div class="text-center py-5">' +
                    '<i class="fas fa-calendar-times fa-4x text-muted mb-3"></i>' +
                    '<h4 class="text-muted">No Appointments Found</h4>' +
                    '<p class="text-muted">You don\'t have any appointments scheduled for ' + formattedDate + '.</p>' +
                    '</div>';
            }
        })
        .catch(function(error) {
            console.error('Error loading appointments:', error);
            section.innerHTML = '<div class="alert alert-danger"><i class="fas fa-exclamation-circle me-2"></i>Failed to load appointments. Please try again.</div>';
        });
    }
}

function navigateDateBar(dayOffset) {
    console.log('Navigate:', dayOffset);
    // Simple navigation - reload page with new date
    var currentUrl = new URL(window.location);
    var currentDate = new Date();
    if (currentUrl.searchParams.has('date')) {
        currentDate = new Date(currentUrl.searchParams.get('date'));
    }
    var newDate = new Date(currentDate);
    newDate.setDate(currentDate.getDate() + dayOffset);

    currentUrl.searchParams.set('date', newDate.toISOString().split('T')[0]);
    window.location.href = currentUrl.toString();
}
